CREATE TABLE public.credit_program_settings (
 id boolean PRIMARY KEY DEFAULT true CHECK (id), welcome_credits integer NOT NULL DEFAULT 50 CHECK (welcome_credits BETWEEN 0 AND 100000), profile_credits integer NOT NULL DEFAULT 5 CHECK (profile_credits BETWEEN 0 AND 100000), score_credits integer NOT NULL DEFAULT 5 CHECK (score_credits BETWEEN 0 AND 100000), referral_credits integer NOT NULL DEFAULT 1 CHECK (referral_credits BETWEEN 0 AND 100000), reminders_enabled boolean NOT NULL DEFAULT true, reminder_hours integer NOT NULL DEFAULT 24 CHECK (reminder_hours BETWEEN 1 AND 720), updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE ON public.credit_program_settings TO authenticated;
GRANT ALL ON public.credit_program_settings TO service_role;
ALTER TABLE public.credit_program_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_settings ON public.credit_program_settings FOR ALL TO authenticated USING (auth.uid()='492ee966-e015-4440-a415-6ad6275a4a9b'::uuid) WITH CHECK (auth.uid()='492ee966-e015-4440-a415-6ad6275a4a9b'::uuid);
CREATE TABLE public.credit_plans (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audience text NOT NULL DEFAULT 'crew' CHECK (audience IN ('crew','manager','fleet')), name text NOT NULL DEFAULT '' CHECK (length(trim(name)) BETWEEN 1 AND 80), price_usd numeric(12,2) NOT NULL DEFAULT 0 CHECK (price_usd>=0), credits integer NOT NULL DEFAULT 0 CHECK (credits BETWEEN 0 AND 1000000), interval text NOT NULL DEFAULT 'once' CHECK (interval IN ('once','month','year')), active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE ON public.credit_plans TO authenticated;
GRANT ALL ON public.credit_plans TO service_role;
ALTER TABLE public.credit_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_plans ON public.credit_plans FOR ALL TO authenticated USING (auth.uid()='492ee966-e015-4440-a415-6ad6275a4a9b'::uuid) WITH CHECK (auth.uid()='492ee966-e015-4440-a415-6ad6275a4a9b'::uuid);
CREATE TABLE public.credit_control_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor uuid NOT NULL DEFAULT auth.uid(), entity text NOT NULL DEFAULT '', before_value jsonb, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.credit_control_audit TO authenticated;
GRANT ALL ON public.credit_control_audit TO service_role;
ALTER TABLE public.credit_control_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_credit_audit ON public.credit_control_audit FOR SELECT TO authenticated USING (auth.uid()='492ee966-e015-4440-a415-6ad6275a4a9b'::uuid);
CREATE FUNCTION public.audit_credit_controls() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at:=now(); INSERT INTO credit_control_audit(actor,entity,before_value,after_value) VALUES(coalesce(auth.uid(),'492ee966-e015-4440-a415-6ad6275a4a9b'::uuid),TG_TABLE_NAME,CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.audit_credit_controls() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER audit_plan_controls BEFORE INSERT OR UPDATE ON public.credit_plans FOR EACH ROW EXECUTE FUNCTION public.audit_credit_controls();
CREATE TRIGGER audit_reward_controls BEFORE INSERT OR UPDATE ON public.credit_program_settings FOR EACH ROW EXECUTE FUNCTION public.audit_credit_controls();
CREATE UNIQUE INDEX uq_credit_milestone_once ON public.credit_ledger(manager_user_id,reason) WHERE reason IN ('cv_completed','assessment_completed','manager_profile_completed');
CREATE FUNCTION public.credit_profile_ready(p_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM crew_profiles p WHERE p.id=p_uid AND NOT coalesce(p.is_test,false) AND length(trim(coalesce(p.first_name,'')))>0 AND coalesce(nullif(p.rank,''),nullif(p.role,'Seafarer'),'')<>'' AND length(trim(coalesce(p.nationality,'')))>0 AND coalesce(p.whatsapp_number,'') ~ '^\+?[0-9]{7,15}$' AND coalesce(p.email,'') ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' AND (p.quick_profile_completed_at IS NOT NULL OR p.onboarding_complete)); $$;
CREATE FUNCTION public.credit_cv_ready(p_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT credit_profile_ready(p_uid) AND EXISTS(SELECT 1 FROM crew_cv_data c WHERE c.user_id=p_uid AND ((jsonb_typeof(c.sea_service)='array' AND jsonb_array_length(CASE WHEN jsonb_typeof(c.sea_service)='array' THEN c.sea_service ELSE '[]'::jsonb END)>0) OR length(coalesce(c.medical->>'cv_original_path',''))>0)); $$;
CREATE FUNCTION public.sync_credit_milestones(p_uid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_profile int; v_score int; BEGIN SELECT profile_credits,score_credits INTO v_profile,v_score FROM credit_program_settings WHERE id; v_profile:=coalesce(v_profile,5); v_score:=coalesce(v_score,5);
IF v_profile>0 AND credit_cv_ready(p_uid) THEN INSERT INTO credit_ledger(manager_user_id,delta,reason) VALUES(p_uid,v_profile,'cv_completed') ON CONFLICT DO NOTHING; END IF;
IF v_profile>0 AND EXISTS(SELECT 1 FROM manager_profiles WHERE user_id=p_uid AND length(trim(coalesce(full_name,'')))>0 AND length(trim(coalesce(company_name,'')))>0 AND length(trim(coalesce(country,'')))>0 AND length(trim(coalesce(phone,'')))>=7) THEN INSERT INTO credit_ledger(manager_user_id,delta,reason) VALUES(p_uid,v_profile,'manager_profile_completed') ON CONFLICT DO NOTHING; END IF;
IF v_score>0 AND EXISTS(SELECT 1 FROM smc_assessments a JOIN crew_profiles p ON p.id=a.crew_profile_id WHERE p.id=p_uid AND NOT coalesce(p.is_test,false) AND a.status='completed' AND a.completed_at IS NOT NULL AND a.overall_score BETWEEN 0 AND 5 AND a.scoring_version IS NOT NULL) THEN INSERT INTO credit_ledger(manager_user_id,delta,reason) VALUES(p_uid,v_score,'assessment_completed') ON CONFLICT DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.credit_profile_ready(uuid),public.credit_cv_ready(uuid),public.sync_credit_milestones(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.credit_milestone_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM sync_credit_milestones(CASE WHEN TG_TABLE_NAME='crew_profiles' THEN NEW.id WHEN TG_TABLE_NAME='smc_assessments' THEN NEW.crew_profile_id ELSE NEW.user_id END); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.credit_milestone_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER credit_profile_milestones AFTER INSERT OR UPDATE ON public.crew_profiles FOR EACH ROW EXECUTE FUNCTION public.credit_milestone_changed();
CREATE TRIGGER credit_cv_milestones AFTER INSERT OR UPDATE ON public.crew_cv_data FOR EACH ROW EXECUTE FUNCTION public.credit_milestone_changed();
CREATE TRIGGER credit_manager_milestones AFTER INSERT OR UPDATE ON public.manager_profiles FOR EACH ROW EXECUTE FUNCTION public.credit_milestone_changed();
CREATE TRIGGER credit_score_milestones AFTER UPDATE OF status,completed_at,overall_score ON public.smc_assessments FOR EACH ROW EXECUTE FUNCTION public.credit_milestone_changed();
CREATE OR REPLACE FUNCTION public.grant_referral_credits() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_email text; v_reward int; BEGIN IF NEW.referred_by IS NULL OR NEW.referred_by=NEW.id OR NOT credit_profile_ready(NEW.id) THEN RETURN NEW; END IF; SELECT lower(email) INTO v_email FROM auth.users WHERE id=NEW.id; IF v_email IS NULL OR v_email ~ '@(tempmail|temp-mail|10minutemail|yopmail|guerrillamail|mailinator|trashmail|sharklasers|getnada|dispostable)\.' THEN RETURN NEW; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(NEW.referred_by::text,0)); IF (SELECT count(*) FROM credit_ledger WHERE manager_user_id=NEW.referred_by AND reason LIKE 'referral_%' AND reason<>'referral_joined' AND created_at>now()-interval '24 hours')>=50 THEN RETURN NEW; END IF;
SELECT referral_credits INTO v_reward FROM credit_program_settings WHERE id; v_reward:=coalesce(v_reward,1); IF v_reward>0 THEN INSERT INTO credit_ledger(manager_user_id,delta,reason) VALUES(NEW.referred_by,v_reward,'referral_'||NEW.id::text) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.claim_welcome_credits() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n int; v_amount int; BEGIN IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false); END IF; SELECT welcome_credits INTO v_amount FROM credit_program_settings WHERE id; v_amount:=coalesce(v_amount,50); IF v_amount>0 THEN INSERT INTO credit_ledger(manager_user_id,delta,reason) VALUES(auth.uid(),v_amount,'welcome_launch') ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; END IF; RETURN jsonb_build_object('ok',true,'granted',coalesce(n,0)>0,'amount',v_amount); END $$;
CREATE OR REPLACE FUNCTION public.get_my_wallet() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); v_code text; s jsonb; BEGIN IF u IS NULL THEN RETURN jsonb_build_object('ok',false); END IF; PERFORM sync_credit_milestones(u); v_code:=upper(substr(replace(u::text,'-',''),1,8)); SELECT to_jsonb(t)-'id'-'updated_at' INTO s FROM credit_program_settings t WHERE id; s:=coalesce(s,'{"welcome_credits":50,"profile_credits":5,"score_credits":5,"referral_credits":1,"reminders_enabled":true,"reminder_hours":24}'::jsonb);
RETURN jsonb_build_object('ok',true,'user_id',u,'balance',coalesce((SELECT sum(delta) FROM credit_ledger WHERE manager_user_id=u),0),'welcome_claimed',EXISTS(SELECT 1 FROM credit_ledger WHERE manager_user_id=u AND reason='welcome_launch'),'code',v_code,'link','https://seaminds.life/?ref='||v_code,'referrals',(SELECT count(*) FROM crew_profiles WHERE referred_by=u),'verified_referrals',(SELECT count(*) FROM credit_ledger WHERE manager_user_id=u AND reason LIKE 'referral_%' AND reason<>'referral_joined'),'referral_credits',coalesce((SELECT sum(delta) FROM credit_ledger WHERE manager_user_id=u AND reason LIKE 'referral_%' AND reason<>'referral_joined'),0),'profile_rewarded',EXISTS(SELECT 1 FROM credit_ledger WHERE manager_user_id=u AND reason IN ('cv_completed','manager_profile_completed')),'score_rewarded',EXISTS(SELECT 1 FROM credit_ledger WHERE manager_user_id=u AND reason='assessment_completed'),'settings',s,'recent',coalesce((SELECT jsonb_agg(x) FROM (SELECT delta,reason,created_at FROM credit_ledger WHERE manager_user_id=u ORDER BY created_at DESC LIMIT 30)x),'[]'::jsonb)); END $$;
CREATE FUNCTION public.admin_credit_report(p_offset int DEFAULT 0,p_search text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS DISTINCT FROM '492ee966-e015-4440-a415-6ad6275a4a9b'::uuid THEN RAISE EXCEPTION 'Owner access required' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('totals',(SELECT jsonb_build_object('balance',coalesce(sum(delta),0),'awarded',coalesce(sum(delta) FILTER(WHERE delta>0),0),'spent',coalesce(-sum(delta) FILTER(WHERE delta<0),0)) FROM credit_ledger),'ledger',coalesce((SELECT jsonb_agg(x) FROM (SELECT l.id,u.email,l.delta,l.reason,l.created_at FROM credit_ledger l LEFT JOIN auth.users u ON u.id=l.manager_user_id WHERE coalesce(u.email,'') ILIKE '%'||p_search||'%' ORDER BY l.created_at DESC,l.id LIMIT 50 OFFSET greatest(p_offset,0))x),'[]'::jsonb),'referrals',coalesce((SELECT jsonb_agg(x) FROM (SELECT p.id,u.email referred_email,r.email referrer_email,credit_profile_ready(p.id) completed,coalesce(l.delta,0) credits,p.referral_claimed_at FROM crew_profiles p LEFT JOIN auth.users u ON u.id=p.id LEFT JOIN auth.users r ON r.id=p.referred_by LEFT JOIN credit_ledger l ON l.manager_user_id=p.referred_by AND l.reason='referral_'||p.id::text WHERE p.referred_by IS NOT NULL AND (coalesce(u.email,'') ILIKE '%'||p_search||'%' OR coalesce(r.email,'') ILIKE '%'||p_search||'%') ORDER BY p.referral_claimed_at DESC NULLS LAST,p.id LIMIT 50 OFFSET greatest(p_offset,0))x),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.admin_credit_report(int,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_credit_report(int,text) TO authenticated;
NOTIFY pgrst,'reload schema';